public void setControlVisibility()
{
    boolean isPromotion = TAMFundTable.FundSourceType == GUPFundSourceType::Promotion;

    TAMFundTable_FundSourceType.visible(true);
    TAMFundTable_CurrencyCode.visible(isPromotion && TAMFundTable.FundValueType == GUPFundValueType::Amount);
    GeneralGrp_Type.visible(!isPromotion);
    TAMFundTable_RebateRelated.visible(isPromotion);
    TAMFundTable_FundValueType.visible(isPromotion);
}
